fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val A = reader.readLine().trim().toLong()

    if (A == 1L) {
        // Only x = 1 has sum of divisors 1
        println(1)
        return
    }

    var count = 0L
    val limit = sqrt(A.toDouble()).toLong()

    for (d in 1..limit) {
        if (A % d != 0L) continue
        val e = A / d

        // Check x = d
        if (sumOfDivisors(d) == A) count++

        // Check x = e if it's different
        if (e != d && sumOfDivisors(e) == A) count++
    }

    println(count)
}

fun sumOfDivisors(n: Long): Long {
    var x = n
    var sum = 1L
    var p = 2L

    while (p * p <= x) {
        if (x % p == 0L) {
            var term = 1L
            var power = 1L
            while (x % p == 0L) {
                x /= p
                power *= p
                term += power
            }
            sum *= term
        }
        p += if (p == 2L) 1L else 2L  // check 2, then only odd numbers
    }

    if (x > 1L) {
        // x is prime
        sum *= (1L + x)
    }

    return sum
}

