            // Check k2 (avoid double-check when k1 == k2)
            if (k2 != k1 && k2 % 2L == 1L) {
                val x = (k2 + 1) / 2
                if (x >= 1 && sumOfDivisors(x) == A) count++
            }
        }
    }

    println(count)
}

