import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.sqrt

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val A = reader.readLine().trim().toLong()

    if (A == 1L) {
        println(1)
        return
    }

    var ans = 0L
    val limit = sqrt(A.toDouble()).toLong()

    fun isPrime(n: Long): Boolean {
        if (n < 2) return false
        if (n == 2L || n == 3L) return true
        if (n % 2L == 0L) return false
        var i = 3L
        while (i * i <= n) {
            if (n % i == 0L) return false
            i += 2
        }
        return true
    }

    // Case 1: x is prime -> J(x) = 1 + x = A
    if (A > 2) {
        val p = A - 1
        if (isPrime(p)) ans++
    }

    // Case 2: x is prime power p^k, k >= 2
    var d = 2L
    while (d <= limit) {
        if (A % d == 0L) {
            val t = A / d
            val p = t - 1
            if (p >= 2 && isPrime(p)) {
                var cur = p
                var sum = 1L + p
                while (sum < A) {
                    cur *= p
                    sum += cur
                }
                if (sum == A) ans++
            }
        }
        d++
    }

    println(ans)
}

