fun isValid(m: Long, A: Long): Boolean {
    // m must be odd
    if (m % 2L == 0L) return false

    val x = A / m
    // x must be integer and positive
    if (x <= 0L) return false

    // m must divide x
    if (x % m != 0L) return false

    // gcd(x/m, m) must be 1
    val k = x / m
    return gcd(k, m) == 1L
}

fun gcd(a: Long, b: Long): Long {
    var x = a
    var y = b
    while (y != 0L) {
        val t = x % y
        x = y
        y = t
    }
    return if (x >= 0) x else -x
}

