fun isValidK(k: Long, A: Long): Boolean {
    // k must be odd
    if (k % 2L == 0L) return false

    val t = A / k
    val x = t - (k - 1) / 2
    if (x <= 0L) return false

    // Check that t is integer and corresponds to sum of divisors
    // Here we only need to ensure that A == k * (x + (x + k - 1)) / 2
    // But since t = A / k, this is already guaranteed by construction.
    return true
}
